mapper.select:
SELECT p.plan_id AS id, p.plan_name AS planName, p.major_id AS majorId, m.major_name AS majorName, p.grade, p.version, p.total_required_credits AS totalRequiredCredits, p.major_elective_min_credits AS majorElectiveMinCredits, p.general_elective_min_credits AS generalElectiveMinCredits, p.plan_status AS planStatus, p.plan_remark AS planRemark, p.gmt_create AS gmtCreate, p.gmt_modified AS gmtModified FROM edu_training_plan p LEFT JOIN edu_major m ON p.major_id = m.major_id AND m.major_deleted = 0 WHERE p.plan_deleted = 0
AND p.major_id = #{majorId}
AND p.grade = #{grade}
AND p.plan_status = #{planStatus}
ORDER BY p.major_id, p.grade DESC, p.version DESC
